```groovy
import com.onemonkeylabs.plugin.ScriptRunner

class ChecklistCompleteTransitionFunction extends ScriptFunction {
    @ScriptFunction("checklistComplete")
    static void checklistComplete(Context context) throws Exception {
        def issue = context.issue
        def transition = context.transition
        def env = context.env
        def log = context.log

        // Get the checklists for the current issue and check their status
        def checklists = issue.getChecklists()?.findAll { it.isDone() }

        // If all checklists are complete, prevent transition
        if (checklists.size() == checklists.unique { it.id }) {
            throw new TransitionException(env.transitions["block"].name, "All checklists are completed. Cannot move issue to ${transition.getName()}.")
        }
    }
}

class Plugin implements Plugin {
    String getKey() {
        return "com.example.plugins:checklistCompleteTransitionFunction"
    }

    List<Class<?>> getFunctions() {
        return [ChecklistCompleteTransitionFunction]
    }
}
```

