#include <iostream>
#include <string>
#include <limits> // For numeric_limits
#include <stdexcept> // For std::out_of_range

// Recursive function to calculate nth Fibonacci number
int fibonacci(int n, int a, int b) {
    if (n == 0 || n == 1) {
        return n == 0 ? a : b;
    } else {
        return fibonacci(n - 1, b, fibonacci(n - 2, a, b));
    }
}

int main() {
    int first{}; // First Fibonacci number
    int second{}; // Second Fibonacci number
    int count{}; // Number of sequence elements to generate
    std::cout << "Enter the first two Fibonacci numbers: ";
    std::cin >> first >> second;
    std::cout << "Enter the number of sequence elements to generate: ";
    std::cin >> count;
    try {
        // Check if inputs are valid
        if (std::cin.fail()) {
            throw std::invalid_argument("Invalid input");
        }
        if (first < 0 || second < 0 || count < 0) {
            throw std::out_of_range("Inputs must not be negative");
        }
        // Generate Fibonacci sequence up to the specified count
        std::cout << first << ", " << second;
        for (int I = 2; I < count; i++) {
            int next = fibonacci(i, first, second);
            std::cout << next << ", ";
            first = second;
            second = next;
        }
        std::cout << fibonacci(count - 1, first, second); // Print last element
        std::cout << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
