RewriteCond %{HTTP:Accept} "application\/json" [NC]
RewriteRule ^(.*)$ serverless/functions/$1 [QSA,L]
RewriteCond %{HTTP:Authorization} .
RewriteRule ^(.*)$ serverless/functions/$1 [E=AUTHORIZATION:%{HTTP:Authorization},QSA,L]
RewriteCond %{HTTP:Cookie} .
RewriteRule ^(.*)$ serverless/functions/$1 [E=COOKIE:%{HTTP:Cookie},QSA,L]
RewriteCond %{HTTP:Content-Type} !^application\/json$
RewriteRule ^(.*)$ pass [P,L]
```

